 static final class Recorder extends HttpsURLConnection{final HttpsURLConnection delegate;final ByteArrayOutputStream raw;final AtomicInteger status;Recorder(HttpsURLConnection d,ByteArrayOutputStream raw,AtomicInteger status){super(d.getURL());delegate=d;this.raw=raw;this.status=status;}public void setConnectTimeout(int n){delegate.setConnectTimeout(n);}public void setReadTimeout(int n){delegate.setReadTimeout(n);}public void setInstanceFollowRedirects(boolean v){delegate.setInstanceFollowRedirects(v);}public void setUseCaches(boolean v){delegate.setUseCaches(v);}public void setRequestProperty(String k,String v){delegate.setRequestProperty(k,v);}public int getResponseCode()throws IOException{int n=delegate.getResponseCode();status.set(n);return n;}public InputStream getInputStream()throws IOException{return new FilterInputStream(delegate.getInputStream()){public int read(byte[] b,int off,int len)throws IOException{int n=super.read(b,off,len);if(n>0){if(raw.size()+n>IndustryDiscoveryModel.MAX)throw new IOException("source exceeds8MiB");raw.write(b,off,n);}return n;}};}public void disconnect(){delegate.disconnect();}public boolean usingProxy(){return delegate.usingProxy();}public void connect()throws IOException{delegate.connect();}public String getCipherSuite(){return delegate.getCipherSuite();}public Certificate[] getLocalCertificates(){return delegate.getLocalCertificates();}public Certificate[] getServerCertificates()throws SSLPeerUnverifiedException{return delegate.getServerCertificates();}}
